import { useState, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Anthropic from '@anthropic-ai/sdk'
import { useUser } from '../context/UserContext'
import { scoreMeal } from '../utils/scoreMeal'
import { isVegKeyword } from '../utils/filterByPreference'
import ScoreBadge from '../components/ScoreBadge'
import BottomNav from '../components/BottomNav'
import styles from './Scan.module.css'

const client = new Anthropic({
  apiKey: import.meta.env.VITE_ANTHROPIC_API_KEY,
  dangerouslyAllowBrowser: true,
})

const MEAL_TIMES = ['breakfast', 'lunch', 'dinner', 'snack']
const MOODS = ['😊 Great', '😐 Okay', '😴 Tired', '💪 Energized', '😩 Sluggish']

export default function Scan() {
  const { dietaryPreference, addDiaryEntry } = useUser()
  const [image, setImage] = useState(null)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState(null)
  const [error, setError] = useState(null)
  const [mealTime, setMealTime] = useState(guessCurrentMeal())
  const [mood, setMood] = useState('')
  const [added, setAdded] = useState(false)
  const fileRef = useRef()
  const cameraRef = useRef()

  function guessCurrentMeal() {
    const h = new Date().getHours()
    if (h < 10) return 'breakfast'
    if (h < 14) return 'lunch'
    if (h < 18) return 'snack'
    return 'dinner'
  }

  function handleFile(e) {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = ev => {
      setImage(ev.target.result)
      setResult(null)
      setError(null)
      setAdded(false)
      analyzeImage(ev.target.result)
    }
    reader.readAsDataURL(file)
  }

  async function analyzeImage(dataUrl) {
    setLoading(true)
    setError(null)
    try {
      if (!import.meta.env.VITE_ANTHROPIC_API_KEY) {
        setResult(getMockResult())
        return
      }

      // Strip data-URL prefix to get raw base64
      const base64 = dataUrl.split(',')[1]

      // Validate image loaded correctly — a real photo is always >50k chars
      console.log('[CalSnap] base64 length:', base64?.length, '— should be 50 000+')
      if (!base64 || base64.length < 5000) {
        throw new Error('Image did not load correctly. Please try again.')
      }

      // Normalize media type — Claude only accepts jpeg/png/gif/webp
      const SUPPORTED = ['image/jpeg', 'image/png', 'image/gif', 'image/webp']
      const rawType = dataUrl.split(';')[0].split(':')[1]
      const mediaType = SUPPORTED.includes(rawType) ? rawType : 'image/jpeg'
      console.log('[CalSnap] mediaType:', mediaType)

      const msg = await client.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 1200,
        system: `You are a precise food recognition and nutrition AI. Your job is to look at the actual image and identify only food items that are CLEARLY VISIBLE.

RULES:
- ONLY describe what you can actually see in the photo. Never invent or assume items.
- Be specific: "Green grapes" not "grapes", "Kiwi slices" not "fruit", "Pineapple chunks" not "tropical fruit".
- If you cannot clearly identify an item, name it "Unidentified item" with low confidence.
- Return ONLY valid JSON — no markdown, no code fences, no commentary.`,
        messages: [{
          role: 'user',
          content: [
            {
              type: 'image',
              source: { type: 'base64', media_type: mediaType, data: base64 }
            },
            {
              type: 'text',
              text: `Look carefully at this specific image. List every individual food item you can actually see. Return this exact JSON structure (no markdown wrapping):
{
  "name": "overall dish or meal name",
  "confidence": number (0-100),
  "isVeg": boolean,
  "alternative": "healthier ${dietaryPreference === 'veg' ? 'vegetarian ' : ''}alternative suggestion",
  "items": [
    {
      "name": "exact specific name of what you see",
      "quantity": "estimated quantity visible (e.g. 1 slice, ~10 pcs, 1 cup)",
      "kcal": number,
      "protein": number,
      "carbs": number,
      "fat": number,
      "isVeg": boolean
    }
  ],
  "kcal": total kcal (sum of all items),
  "protein": total protein grams,
  "carbs": total carbs grams,
  "fat": total fat grams
}`
            }
          ]
        }]
      })

      const raw = msg.content[0].text.trim()
      // Strip markdown code fences in case Claude adds them despite instructions
      const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim()
      const json = JSON.parse(cleaned)
      const score = scoreMeal(json)
      setResult({ ...json, score })
    } catch (e) {
      console.error('[CalSnap] analyzeImage error:', e)
      setError(
        e.message?.startsWith('Image did not load')
          ? e.message
          : 'Could not analyze the image. Please try again.'
      )
    } finally {
      setLoading(false)
    }
  }

  function getMockResult() {
    return {
      name: 'Mixed Grain Bowl',
      confidence: 87,
      isVeg: true,
      score: 8,
      alternative: dietaryPreference === 'veg'
        ? 'Try adding edamame for more complete protein'
        : 'Add grilled chicken for extra protein',
      items: [
        { name: 'Brown rice', quantity: '½ cup', kcal: 110, protein: 2, carbs: 23, fat: 1, isVeg: true },
        { name: 'Roasted chickpeas', quantity: '¼ cup', kcal: 120, protein: 6, carbs: 18, fat: 3, isVeg: true },
        { name: 'Avocado', quantity: '2 slices', kcal: 80, protein: 1, carbs: 4, fat: 7, isVeg: true },
        { name: 'Mixed greens', quantity: '1 cup', kcal: 15, protein: 1, carbs: 3, fat: 0, isVeg: true },
        { name: 'Tahini dressing', quantity: '1 tbsp', kcal: 95, protein: 3, carbs: 4, fat: 8, isVeg: true },
      ],
      kcal: 420,
      protein: 13,
      carbs: 52,
      fat: 19,
    }
  }

  function addToDiary() {
    if (!result) return
    addDiaryEntry({
      name: result.name,
      kcal: result.kcal,
      protein: result.protein,
      carbs: result.carbs,
      fat: result.fat,
      score: result.score,
      isVeg: result.isVeg ?? isVegKeyword(result.name),
      mealTime,
      mood: mood.split(' ')[1] || '',
      items: result.items || [],
    })
    setAdded(true)
  }

  const itemCount = result?.items?.length || 0

  return (
    <div className={`page ${styles.scan}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Snap a meal</h1>
        <p className={styles.sub}>Point at food to get instant nutrition</p>
      </div>

      {/* Viewfinder */}
      <div className={styles.viewfinder} onClick={() => !image && fileRef.current.click()}>
        {image ? (
          <img src={image} alt="food" className={styles.preview} />
        ) : (
          <div className={styles.placeholder}>
            <div className={styles.corner} />
            <CameraIcon />
            <p className={styles.placeholderText}>Tap to take / upload a photo</p>
          </div>
        )}
        {loading && (
          <motion.div className={styles.loader}
            animate={{ opacity: [0.5, 1, 0.5] }}
            transition={{ duration: 1.2, repeat: Infinity }}>
            <div className={styles.pulse} />
            <span>Analyzing with AI...</span>
          </motion.div>
        )}
      </div>

      <div className={styles.actions}>
        <button className={styles.uploadBtn} onClick={() => fileRef.current.click()}>
          Upload photo
        </button>
        <button className={styles.cameraBtn} onClick={() => cameraRef.current.click()}>
          Camera
        </button>
      </div>

      <input ref={fileRef} type="file" accept="image/*" hidden onChange={handleFile} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" hidden onChange={handleFile} />

      {error && <p className={styles.error}>{error}</p>}

      {/* Result card */}
      <AnimatePresence>
        {result && !loading && (
          <motion.div className={styles.result}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.4 }}>

            {/* Meal header */}
            <div className={styles.resultHeader}>
              <span className={styles.vegDot} style={{ background: result.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }} />
              <h2 className={styles.foodName}>{result.name}</h2>
              <ScoreBadge score={result.score} />
            </div>

            {/* Total macro chips */}
            <div className={styles.macroRow}>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-text)' }}>
                <span className={styles.macroVal}>{result.kcal}</span>
                <span className={styles.macroLbl}>kcal</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-text)' }}>
                <span className={styles.macroVal}>{result.protein}g</span>
                <span className={styles.macroLbl}>protein</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-lavender)', color: 'var(--lavender-text)' }}>
                <span className={styles.macroVal}>{result.carbs}g</span>
                <span className={styles.macroLbl}>carbs</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-peach)', color: 'var(--peach-text)' }}>
                <span className={styles.macroVal}>{result.fat}g</span>
                <span className={styles.macroLbl}>fat</span>
              </div>
            </div>

            <div className={styles.confidence}>
              Confidence: <strong>{result.confidence}%</strong>
            </div>

            {result.alternative && (
              <div className={styles.altCard}>
                <span className={styles.altLabel}>Healthier alternative</span>
                <p className={styles.altText}>{result.alternative}</p>
              </div>
            )}

            {/* Item breakdown */}
            {result.items && result.items.length > 0 && (
              <div className={styles.breakdown}>
                <p className={styles.breakdownTitle}>What's on your plate 🌸</p>
                {result.items.map((item, i) => (
                  <div key={i} className={styles.itemRow}>
                    <div className={styles.itemLeft}>
                      <span
                        className={styles.itemDot}
                        style={{ background: item.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }}
                      />
                      <div className={styles.itemInfo}>
                        <div className={styles.itemNameLine}>
                          {item.name}
                          {item.quantity && (
                            <span className={styles.itemQty}> · {item.quantity}</span>
                          )}
                        </div>
                        <div className={styles.itemMacros}>
                          <span className={styles.itemPill} style={{ background: 'var(--surface-rose)', color: 'var(--rose-text)' }}>
                            P {item.protein}g
                          </span>
                          <span className={styles.itemPill} style={{ background: 'var(--surface-lavender)', color: 'var(--lavender-text)' }}>
                            C {item.carbs}g
                          </span>
                          <span className={styles.itemPill} style={{ background: 'var(--surface-peach)', color: 'var(--peach-text)' }}>
                            F {item.fat}g
                          </span>
                        </div>
                      </div>
                    </div>
                    <span className={styles.itemKcal}>{item.kcal} kcal</span>
                  </div>
                ))}

                {/* Total row */}
                <div className={styles.totalRow}>
                  <span className={styles.totalLabel}>Total</span>
                  <div className={styles.totalMacros}>
                    <span>P {result.protein}g</span>
                    <span>C {result.carbs}g</span>
                    <span>F {result.fat}g</span>
                  </div>
                  <span className={styles.totalKcal}>{result.kcal} kcal</span>
                </div>
              </div>
            )}

            {/* Meal time selector */}
            <div className={styles.timeRow}>
              {MEAL_TIMES.map(t => (
                <button
                  key={t}
                  className={`${styles.timeChip} ${mealTime === t ? styles.timeActive : ''}`}
                  onClick={() => setMealTime(t)}>
                  {t}
                </button>
              ))}
            </div>

            {/* Mood tag */}
            <div className={styles.moodRow}>
              <span className={styles.moodLabel}>How do you feel?</span>
              <div className={styles.moodChips}>
                {MOODS.map(m => (
                  <button
                    key={m}
                    className={`${styles.moodChip} ${mood === m ? styles.moodActive : ''}`}
                    onClick={() => setMood(m === mood ? '' : m)}>
                    {m}
                  </button>
                ))}
              </div>
            </div>

            {added ? (
              <div className={styles.addedMsg}>
                {itemCount > 0 ? `${itemCount} items added to diary ✓` : 'Added to diary ✓'}
              </div>
            ) : (
              <button className={styles.addBtn} onClick={addToDiary}>
                Add {itemCount > 0 ? `${itemCount} items` : 'meal'} to Diary
              </button>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  )
}

function CameraIcon() {
  return (
    <svg width="48" height="48" viewBox="0 0 24 24" fill="none" opacity="0.4">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" stroke="#d4607a" strokeWidth="1.5" fill="none" strokeLinejoin="round" />
      <circle cx="12" cy="13" r="4" stroke="#d4607a" strokeWidth="1.5" />
    </svg>
  )
}

import { useState, useCallback } from 'react'
import Anthropic from '@anthropic-ai/sdk'

const client = new Anthropic({
  apiKey: import.meta.env.VITE_ANTHROPIC_API_KEY,
  dangerouslyAllowBrowser: true,
})

export function useAiCoach() {
  const [tip, setTip] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  const fetchTip = useCallback(async ({ totals, goals, preference, fitnessGoal }) => {
    if (!import.meta.env.VITE_ANTHROPIC_API_KEY) {
      setTip(getLocalTip(totals, goals, preference))
      return
    }
    setLoading(true)
    setError(null)
    try {
      const dietLabel = preference === 'veg' ? 'vegetarian' : 'non-vegetarian'
      const msg = await client.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 200,
        system: [
          {
            type: 'text',
            text: 'You are Petal, a warm AI wellness coach for a calorie tracking app. Give ONE short (2-3 sentence), personalized, encouraging tip. Use one flower/nature metaphor. No markdown.',
            cache_control: { type: 'ephemeral' }
          }
        ],
        messages: [{
          role: 'user',
          content: `Stats: ${totals.kcal}/${goals.kcal} kcal, P${totals.protein}g/${goals.protein}g, C${totals.carbs}g/${goals.carbs}g, F${totals.fat}g/${goals.fat}g. Diet: ${dietLabel}. Goal: ${fitnessGoal}. Only suggest ${dietLabel} foods.`
        }]
      })
      setTip(msg.content[0].text)
    } catch (e) {
      setError(e.message)
      setTip(getLocalTip(totals, goals, preference))
    } finally {
      setLoading(false)
    }
  }, [])

  return { tip, loading, error, fetchTip }
}

function getLocalTip(totals, goals, preference) {
  const remaining = (goals.kcal || 2000) - (totals.kcal || 0)
  if (remaining < 200) return preference === 'veg'
    ? 'You\'re blooming beautifully today! A light dal soup or fruit bowl would round off your day perfectly.'
    : 'You\'re almost at your goal! A light salad or lean protein snack would be a lovely finish.'
  if ((totals.protein || 0) < (goals.protein || 50) * 0.5) return preference === 'veg'
    ? 'Your petals need protein to flourish! Try adding paneer, lentils, or Greek yogurt to your next meal.'
    : 'Your body blooms with protein! Consider adding eggs, grilled chicken, or Greek yogurt to stay strong.'
  return preference === 'veg'
    ? 'You\'re nurturing yourself beautifully! Keep your meals colorful with veggies and whole grains.'
    : 'Great balance today! Keep nourishing yourself with whole foods and stay hydrated like a garden in morning light.'
}

import { useState, useEffect } from 'react'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell,
  LineChart, Line, Legend, CartesianGrid
} from 'recharts'
import { motion } from 'framer-motion'
import Anthropic from '@anthropic-ai/sdk'
import { useUser } from '../context/UserContext'
import { useCalorieData } from '../hooks/useCalorieData'
import BottomNav from '../components/BottomNav'
import styles from './Progress.module.css'

const client = new Anthropic({
  apiKey: import.meta.env.VITE_ANTHROPIC_API_KEY,
  dangerouslyAllowBrowser: true,
})

function getWeekKey() {
  const d = new Date()
  const jan1 = new Date(d.getFullYear(), 0, 1)
  const week = Math.ceil(((d - jan1) / 86400000 + jan1.getDay() + 1) / 7)
  return `${d.getFullYear()}-W${week}`
}

export default function Progress() {
  const { weeklyReport, saveWeeklyReport, calorieGoal, dietaryPreference, fitnessGoal } = useUser()
  const { weekData, bestDay, worstDay } = useCalorieData()
  const [reportLoading, setReportLoading] = useState(false)
  const weekKey = getWeekKey()
  const report = weeklyReport[weekKey]

  const isSunday = new Date().getDay() === 0

  async function generateReport() {
    setReportLoading(true)
    try {
      if (!import.meta.env.VITE_ANTHROPIC_API_KEY) {
        saveWeeklyReport(weekKey, getMockReport())
        return
      }
      const summary = weekData.map(d => `${d.label}: ${d.kcal} kcal, P${d.protein}g C${d.carbs}g F${d.fat}g`).join('\n')
      const msg = await client.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 400,
        system: [
          {
            type: 'text',
            text: 'You are Petal, a warm wellness coach. Write encouraging weekly nutrition reports (3-4 sentences). Include best day, macro gaps, and a next-week goal. Use one flower/nature metaphor. No markdown.',
            cache_control: { type: 'ephemeral' }
          }
        ],
        messages: [{
          role: 'user',
          content: `Diet: ${dietaryPreference}, Goal: ${fitnessGoal}, Daily target: ${calorieGoal} kcal\n${summary}`
        }]
      })
      saveWeeklyReport(weekKey, {
        summary: msg.content[0].text,
        bestDay: bestDay?.label || '—',
        worstDay: worstDay?.label || '—',
        generatedAt: new Date().toISOString()
      })
    } catch (e) {
      saveWeeklyReport(weekKey, getMockReport())
    } finally {
      setReportLoading(false)
    }
  }

  function getMockReport() {
    return {
      summary: `You've been blooming beautifully this week! Your ${bestDay?.label || 'best day'} was a highlight — great calorie balance and macro distribution. Watch your protein intake mid-week; try adding lentils or paneer to lunch. For next week, aim to hit 80% of your protein goal every day — your body will thank you with renewed energy.`,
      bestDay: bestDay?.label || '—',
      worstDay: worstDay?.label || '—',
      generatedAt: new Date().toISOString()
    }
  }

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload?.length) {
      return (
        <div className={styles.tooltip}>
          <p className={styles.tooltipLabel}>{label}</p>
          <p style={{ color: 'var(--rose-dark)' }}>{payload[0].value} kcal</p>
        </div>
      )
    }
    return null
  }

  return (
    <div className={`page ${styles.progress}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Weekly Progress</h1>
        <p className={styles.sub}>Your bloom journey this week</p>
      </div>

      {/* Calorie bar chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Daily Calories</h3>
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={weekData} margin={{ top: 4, right: 0, left: -20, bottom: 0 }}>
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="kcal" radius={[6, 6, 0, 0]}>
              {weekData.map((d, i) => (
                <Cell key={i} fill={d.kcal <= calorieGoal ? '#f9c8d8' : '#d4607a'} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Macro trend line chart */}
      <div className={styles.card}>
        <h3 className={styles.cardTitle}>Macro Trends</h3>
        <ResponsiveContainer width="100%" height={180}>
          <LineChart data={weekData} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#ecdee8" />
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#806068' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#806068' }} axisLine={false} tickLine={false} />
            <Tooltip />
            <Legend wrapperStyle={{ fontSize: 11 }} />
            <Line type="monotone" dataKey="protein" stroke="#d4607a" strokeWidth={2} dot={false} name="Protein" />
            <Line type="monotone" dataKey="carbs"   stroke="#9060c8" strokeWidth={2} dot={false} name="Carbs" />
            <Line type="monotone" dataKey="fat"     stroke="#d07030" strokeWidth={2} dot={false} name="Fat" />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Best / worst day */}
      <div className={styles.dayCards}>
        <div className={styles.dayCard} style={{ background: 'var(--surface-matcha)', borderColor: 'var(--matcha)' }}>
          <span className={styles.dayEmoji}>✨</span>
          <span className={styles.dayLabel}>Best day</span>
          <span className={styles.dayValue}>{bestDay?.label || '—'}</span>
          {bestDay && <span className={styles.dayKcal}>{bestDay.kcal} kcal</span>}
        </div>
        <div className={styles.dayCard} style={{ background: 'var(--surface-rose)', borderColor: 'var(--rose)' }}>
          <span className={styles.dayEmoji}>🌿</span>
          <span className={styles.dayLabel}>Most calories</span>
          <span className={styles.dayValue}>{worstDay?.label || '—'}</span>
          {worstDay && <span className={styles.dayKcal}>{worstDay.kcal} kcal</span>}
        </div>
      </div>

      {/* Weekly AI Report */}
      <div className={styles.reportCard}>
        <h3 className={styles.cardTitle}>Weekly AI Report</h3>
        {report ? (
          <div>
            <p className={styles.reportText}>{report.summary}</p>
            <p className={styles.reportMeta}>Generated {new Date(report.generatedAt).toLocaleDateString()}</p>
          </div>
        ) : (
          <div className={styles.reportEmpty}>
            <p>{isSunday ? 'Generate your weekly bloom report!' : 'Available every Sunday — keep logging!'}</p>
            <button
              className={styles.reportBtn}
              onClick={generateReport}
              disabled={reportLoading}>
              {reportLoading ? 'Generating...' : 'Generate Report'}
            </button>
          </div>
        )}
      </div>

      <BottomNav />
    </div>
  )
}

